 out=ROOT/'outputs/r78';out.mkdir(exist_ok=True);auditpath=ROOT/'outputs/r77/stock_interval_audit.parquet';d=pd.read_parquet(auditpath);bad=d[~(d.price_valid&d.chain_stable)];receipt=json.loads((ROOT/'outputs/r77/receipt.json').read_text());paths={Path(p).stem:Path(p) for p in receipt['price_partitions']};intervalpath=ROOT/'outputs/r77/intervals.json';iv={(x['method'],pd.Timestamp(x['origin'])):x for x in json.loads(intervalpath.read_text())};calendar=pd.DatetimeIndex(pd.read_parquet(CACHE/'forecast_v5/CSI_ALL.parquet').index);rows=[];reads={}
