 js(out/'summary.json',summary);inputs=[auditpath,intervalpath,ROOT/'outputs/r77/receipt.json',ROOT/'protocols/r78.json',Path(__file__),CACHE/'forecast_v5/CSI_ALL.parquet'];js(out/'receipt.json',dict(reads={str(p):sha(p) for p in inputs},price_partitions=reads,scope='all failed fixed-stock interval rows; no repair or removal'));print(json.dumps(summary,ensure_ascii=False))
